<section class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><a href="<?= e(url('/pelanggan')) ?>" class="text-sm font-semibold text-primary hover:underline">← Data pelanggan</a><h1 class="mt-3 text-2xl font-bold text-slate-900"><?= e($pelanggan['nama_pelanggan']) ?></h1><p class="mt-1 font-mono text-sm text-slate-500">NPA <?= e($pelanggan['npa']) ?></p></div><div class="flex gap-2"><?php if (Auth::isAdmin()): ?><a href="<?= e(url('/pelanggan/' . rawurlencode($pelanggan['npa']) . '/edit')) ?>" class="rounded-xl border border-primary px-4 py-2.5 text-sm font-semibold text-primary hover:bg-blue-50">Ubah Data</a><?php endif; ?><span class="badge badge-<?= $kategori['key'] === 'aktif' ? 'disetujui' : ($kategori['key'] === 'nonaktif_lama' ? 'ditolak' : 'pending') ?> self-center"><?= e($kategori['label']) ?></span></div></section>
<section class="rounded-2xl bg-white p-5 shadow-card sm:p-7"><div class="flex flex-col gap-5 border-b border-slate-100 pb-6 sm:flex-row sm:items-center"><div class="flex h-16 w-16 items-center justify-center rounded-full bg-blue-100 text-xl font-bold text-primary"><?= e(strtoupper(mb_substr($pelanggan['nama_pelanggan'], 0, 1))) ?></div><div class="flex-1"><h2 class="text-lg font-bold text-slate-900">Profil Pelanggan</h2><p class="mt-1 text-sm text-slate-500"><?= e($pelanggan['alamat']) ?></p></div><?php if ($kategori['key'] !== 'aktif'): ?><p class="rounded-xl bg-amber-50 px-4 py-3 text-sm text-warning">Nonaktif selama <b><?= e((string) $kategori['days']) ?> hari</b></p><?php endif; ?></div><dl class="mt-6 grid gap-5 sm:grid-cols-2 lg:grid-cols-3"><div><dt class="detail-label">NPA</dt><dd class="detail-value font-mono"><?= e($pelanggan['npa']) ?></dd></div><div><dt class="detail-label">No. Telepon</dt><dd class="detail-value"><?= e($pelanggan['no_telepon'] ?: '—') ?></dd></div><div><dt class="detail-label">Golongan</dt><dd class="detail-value"><?= e($pelanggan['golongan'] ?: '—') ?></dd></div><div><dt class="detail-label">Status Database</dt><dd class="detail-value"><?= e($pelanggan['status']) ?></dd></div><div><dt class="detail-label">Tanggal Nonaktif</dt><dd class="detail-value"><?= e(formatTanggal($pelanggan['tgl_nonaktif'])) ?></dd></div><div><dt class="detail-label">Dibuat</dt><dd class="detail-value"><?= e(formatTanggalWaktu($pelanggan['created_at'])) ?></dd></div></dl></section>
<section class="mt-6 grid gap-6 xl:grid-cols-2"><article class="overflow-hidden rounded-2xl bg-white shadow-card"><header class="flex items-center justify-between border-b border-slate-100 px-6 py-4"><h2 class="font-bold text-slate-900">Tagihan</h2><a href="<?= e(url('/tagihan?q=' . rawurlencode($pelanggan['npa']))) ?>" class="text-sm font-semibold text-primary">Lihat semua</a></header><?php if ($tagihan): ?><div class="table-wrap"><table class="w-full min-w-[500px] text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="px-6 py-3">Periode</th><th class="px-6 py-3">Tagihan</th><th class="px-6 py-3">Status</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($tagihan as $row): ?><tr><td class="px-6 py-3 text-slate-600"><?= e(formatTanggal($row['periode'])) ?></td><td class="px-6 py-3 font-medium"><?= e(formatRupiah($row['total_tagihan'])) ?></td><td class="px-6 py-3"><span class="badge badge-<?= $row['status_bayar'] === 'Lunas' ? 'disetujui' : 'pending' ?>"><?= e($row['status_bayar']) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php else: $emptyTitle='Belum ada tagihan'; $emptyText='Riwayat tagihan pelanggan belum tersedia.'; require root_path('app/Views/components/empty-state.php'); endif; ?></article>
<article class="overflow-hidden rounded-2xl bg-white shadow-card"><header class="border-b border-slate-100 px-6 py-4"><h2 class="font-bold text-slate-900">Pemutusan</h2></header><?php if ($pemutusan): ?><div class="divide-y divide-slate-100"><?php foreach ($pemutusan as $row): ?><div class="px-6 py-4"><div class="flex justify-between gap-4"><div><p class="font-semibold text-slate-800"><?= e($row['jenis_tindakan']) ?></p><p class="mt-1 text-sm text-slate-500"><?= e(formatTanggal($row['tgl_pemutusan'])) ?> · <?= e($row['status_pemutusan']) ?></p></div><p class="font-semibold text-slate-700"><?= e(formatRupiah($row['biaya_tindakan'])) ?></p></div></div><?php endforeach; ?></div><?php else: $emptyTitle='Belum ada riwayat pemutusan'; $emptyText='Data tindakan pemutusan belum tersedia.'; require root_path('app/Views/components/empty-state.php'); endif; ?></article>
<article class="overflow-hidden rounded-2xl bg-white shadow-card xl:col-span-2"><header class="flex items-center justify-between border-b border-slate-100 px-6 py-4"><h2 class="font-bold text-slate-900">Daftar Ulang & Riwayat</h2><?php if (Auth::isAdmin() && $kategori['key'] === 'nonaktif_lama'): ?><a href="<?= e(url('/daftar-ulang/create?npa=' . rawurlencode($pelanggan['npa']))) ?>" class="text-sm font-semibold text-primary">Ajukan daftar ulang</a><?php endif; ?></header><?php if ($daftarUlang): ?><div class="table-wrap"><table class="w-full min-w-[620px] text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="px-6 py-3">No. Registrasi</th><th class="px-6 py-3">Tanggal</th><th class="px-6 py-3">Biaya</th><th class="px-6 py-3">Status</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($daftarUlang as $row): ?><tr><td class="px-6 py-3"><a class="font-mono font-semibold text-primary hover:underline" href="<?= e(url('/daftar-ulang/' . rawurlencode($row['no_registrasi']))) ?>"><?= e($row['no_registrasi']) ?></a></td><td class="px-6 py-3 text-slate-600"><?= e(formatTanggalWaktu($row['tgl_permohonan'])) ?></td><td class="px-6 py-3 font-medium"><?= e(formatRupiah($row['biaya_daftar_ulang'])) ?></td><td class="px-6 py-3"><span class="badge badge-<?= strtolower($row['status_verifikasi']) ?>"><?= e($row['status_verifikasi']) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php else: $emptyTitle='Belum ada pengajuan daftar ulang'; $emptyText='Pengajuan daftar ulang akan tampil sebagai riwayat di sini.'; require root_path('app/Views/components/empty-state.php'); endif; ?></article></section>
